Core functionality – presets and flat config (REQ-CONFIG-PRESETS, REQ-FLAT-CONFIG):
- src/index.ts defines recommended and strict presets in ESLint v9 flat-config style:
  """ts
  const TRACEABILITY_RULE_SEVERITIES: Readonly<Record> = {
    "traceability/require-story-annotation": "error",
    "traceability/require-req-annotation": "error",
    "traceability/require-branch-annotation": "error",
    "traceability/valid-annotation-format": "warn",
    "traceability/valid-story-reference": "error",
    "traceability/valid-req-reference": "error",
    "traceability/prefer-implements-annotation": "warn",
  } as const;

  function createTraceabilityFlatConfig() {
    return {
      plugins: {
        traceability: {},
      },
      rules: {
        ...TRACEABILITY_RULE_SEVERITIES,
      },
    };
  }

  const configs = {
    recommended: [createTraceabilityFlatConfig()],
    strict: [createTraceabilityFlatConfig()],
  };

  export { rules, configs, maintenance };
  export default { rules, configs, maintenance };
  """
- tests/plugin-default-export-and-configs.test.ts validates these presets and their contents:
  """ts
  import plugin, { rules, configs } from "../src/index";

  it("[REQ-PLUGIN-STRUCTURE] default export includes rules and configs", () => {
    expect(plugin.rules).toBe(rules);
    expect(plugin.configs).toBe(configs);
  });

  it("[REQ-RULE-REGISTRY] configs.recommended contains correct rule configuration", () => {
    const recommendedRules = configs.recommended[0].rules;
    expect(recommendedRules).toHaveProperty(
      "traceability/require-story-annotation", "error",
    );
    expect(recommendedRules).toHaveProperty(
      "traceability/require-req-annotation", "error",
    );
    expect(recommendedRules).toHaveProperty(
      "traceability/require-branch-annotation", "error",
    );
  });

  it("[REQ-CONFIG-SYSTEM] configs.strict contains same rules as recommended", () => {
    const strictRules = configs.strict[0].rules;
    expect(strictRules).toEqual(configs.recommended[0].rules);
  });

  it("[REQ-ERROR-SEVERITY] configs.recommended maps valid-annotation-format to warn and others to error", () => {
    const recommendedRules = configs.recommended[0].rules;
    expect(recommendedRules).toHaveProperty(
      "traceability/valid-annotation-format", "warn",
    );
    expect(recommendedRules).toHaveProperty(
      "traceability/require-story-annotation", "error",
    );
    expect(recommendedRules).toHaveProperty(
      "traceability/require-req-annotation", "error",
    );
    expect(recommendedRules).toHaveProperty(
      "traceability/require-branch-annotation", "error",
    );
    expect(recommendedRules).toHaveProperty(
      "traceability/valid-story-reference", "error",
    );
    expect(recommendedRules).toHaveProperty(
      "traceability/valid-req-reference", "error",
    );
    expect(recommendedRules).toHaveProperty(
      "traceability/prefer-implements-annotation", "warn",
    );
  });
