Flat-config quality and integration (REQ-FLAT-CONFIG, REQ-PROJECT-INTEGRATION, Integration acceptance criterion):
- Project itself uses ESLint v9 flat config and integrates the plugin: eslint.config.js
  """js
  /**
   * ESLint flat config for Traceability Plugin
   * @story docs/stories/002.0-DEV-ESLINT-CONFIG.story.md
   * @req REQ-FLAT-CONFIG - Setup ESLint v9 flat config for plugin usage
   */
  const typescriptParser = require("@typescript-eslint/parser");
  const js = require("@eslint/js");

  let plugin;
  try {
    plugin = require("./src/index.js");
  } catch (eSrc) {
    try {
      plugin = require("./lib/src/index.js");
    } catch (eLib) {
      const inCI = process.env.NODE_ENV === "ci" || process.env.CI === "true";
      if (inCI) {
        throw new Error(
          "Traceability plugin not found. Expected ./src/index.js or ./lib/src/index.js to be present in CI.",
        );
      } else {
        console.warn("Traceability plugin not built yet, skipping traceability rules");
        plugin = {};
      }
    }
  }

  module.exports = [
    js.configs.recommended,
    { files: ["*.config.js", "*.config.mjs", "jest.config.js"], ... },
    { files: ["**/*.ts", "**/*.tsx"], languageOptions: { parser: typescriptParser, ... }, plugins: { ...(plugin.rules ? { traceability: plugin } : {}) }, rules: { ... } },
    { files: ["**/*.js", "**/*.jsx"], ... },
    { files: ["**/*.test.{js,ts,tsx}", ...], ... },
    { ignores: ["lib/**", "node_modules/**", "coverage/**", "docs/**", "*.md", ...] },
  ];
  """
- CLI integration test runs ESLint with this config and plugin: tests/integration/cli-integration.test.ts
  """ts
  const eslintPkgDir = path.dirname(require.resolve("eslint/package.json"));
  const eslintCliPath = path.join(eslintPkgDir, "bin", "eslint.js");
  const configPath = path.resolve(__dirname, "../../eslint.config.js");

  function runEslint(code: string, rule: string) {
    const args = [
      "--no-config-lookup",
      "--config", configPath,
      "--stdin",
      "--stdin-filename", "foo.js",
      "--rule", "no-unused-vars:off",
      "--rule", rule,
    ];
    const result = spawnSync(process.execPath, [eslintCliPath, ...args], {
      encoding: "utf-8",
      input: code,
    });
    return result;
  }

  it.each(tests)("[REQ-PLUGIN-STRUCTURE] $name", ({ code, rule, expectedStatus }) => {
    const result = runEslint(code, rule);
    expect(result.status).toBe(expectedStatus);
  });
  """

Rule options, customizable paths, and config validation (REQ-RULE-OPTIONS, REQ-CUSTOMIZABLE-PATHS, REQ-CONFIG-VALIDATION, Error Handling criterion):
- valid-story-reference exposes configurable directories and flags with JSON Schema validation: src/rules/valid-story-reference.ts
  """ts
  const defaultStoryDirs = ["docs/stories", "stories"]; // customizable default

  export default {
    meta: {
      schema: [
        {
          type: "object",
          properties: {
            storyDirectories: { type: "array", items: { type: "string" } },
            allowAbsolutePaths: { type: "boolean" },
            requireStoryExtension: { type: "boolean" },
          },
          additionalProperties: false,
        },
      ],
    },
    create(context: Rule.RuleContext) {
      const opts = context.options[0] as {
        storyDirectories?: string[];
        allowAbsolutePaths?: boolean;
        requireStoryExtension?: boolean;
      } | undefined;
      const storyDirs = opts?.storyDirectories || defaultStoryDirs;
      const allowAbsolute = opts?.allowAbsolutePaths || false;
      const requireExt = opts?.requireStoryExtension !== false;
      // ... use storyDirs/allowAbsolute/requireExt in validation ...
    },
  } as Rule.RuleModule;
  """
